import java.util.Scanner;

public class EmployeeSalary {
    private int empNo;
    private String name;
    private double basic, da, hra, pf, netPay;

    public void accept() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter Employee Number : ");
        empNo = sc.nextInt();
        sc.nextLine(); // consume newline
        System.out.print("Enter Employee Name   : ");
        name = sc.nextLine();
        System.out.print("Enter Basic Salary    : ");
        basic = sc.nextDouble();
    }

    public void calculate() {
        da = 0.30 * basic;
        hra = 0.15 * basic;
        pf = 0.12 * basic;
        netPay = basic + da + hra - pf;
    }

    public void display() {
        System.out.println("\n========================================");
        System.out.println("          EMPLOYEE SALARY SLIP          ");
        System.out.println("========================================");
        System.out.println("Employee No  : " + empNo);
        System.out.println("Employee Name: " + name);
        System.out.printf("Basic Salary : Rs. %.2f\n", basic);
        System.out.printf("D.A. (30%%)   : Rs. %.2f\n", da);
        System.out.printf("H.R.A. (15%%) : Rs. %.2f\n", hra);
        System.out.printf("P.F. (12%%)   : Rs. %.2f\n", pf);
        System.out.println("----------------------------------------");
        System.out.printf("NET TAKE-HOME: Rs. %.2f\n", netPay);
        System.out.println("========================================");
    }

    public static void main(String[] args) {
        EmployeeSalary emp = new EmployeeSalary();
        emp.accept();
        emp.calculate();
        emp.display();
    }
}
