import java.util.Scanner;

public class BinarySearchNames {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] names = {
            "ANANYA", "ARJUN", "DEBASHIS", "ISHAN", "MAMATA",
            "PRIYA", "RAHUL", "ROHAN", "SNEHA", "VIKRAM"
        };

        System.out.println("Presorted Student Names:");
        for (int i = 0; i < names.length; i++) {
            System.out.println("[" + i + "] " + names[i]);
        }

        System.out.print("\nEnter Name to Search: ");
        String target = sc.next().toUpperCase();

        int low = 0, high = names.length - 1;
        boolean found = false;
        int foundIdx = -1;

        while (low <= high) {
            int mid = (low + high) / 2;
            int cmp = target.compareTo(names[mid]);

            if (cmp == 0) {
                found = true;
                foundIdx = mid;
                break;
            } else if (cmp < 0) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        if (found) {
            System.out.println("Name found at index: " + foundIdx);
        } else {
            System.out.println("Name not present in the record.");
        }
    }
}
```

