import java.util.Scanner;

public class KrishnamurthyNumber {
    // Helper function to compute factorial of a single digit
    public static int factorial(int d) {
        int fact = 1;
        for (int i = 1; i <= d; i++) {
            fact *= i;
        }
        return fact;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter an integer: ");
        int num = sc.nextInt();

        int temp = num;
        int sumFact = 0;

        while (temp > 0) {
            int digit = temp % 10;
            sumFact += factorial(digit);
            temp /= 10;
        }

        System.out.println("Number: " + num);
        System.out.println("Sum of factorials of digits: " + sumFact);

        if (sumFact == num) {
            System.out.println(num + " is a SPECIAL / KRISHNAMURTHY NUMBER.");
        } else {
            System.out.println(num + " is NOT a Special number.");
        }
    }
}
```

