public class CheckOverloading {
    public void check(int n, int d) {
        int count = 0;
        int temp = Math.abs(n);
        while (temp > 0) {
            if (temp % 10 == d) count++;
            temp /= 10;
        }
        System.out.println("Frequency of digit '" + d + "' in " + n + " is: " + count);
    }

    public void check(String s, char c) {
        int count = 0;
        char target = Character.toUpperCase(c);
        String upper = s.toUpperCase();

        for (int i = 0; i < upper.length(); i++) {
            if (upper.charAt(i) == target) count++;
        }
        System.out.println("Frequency of character '" + c + "' in \"" + s + "\" is: " + count);
    }

    public static void main(String[] args) {
        CheckOverloading obj = new CheckOverloading();
        obj.check(1842883, 8);
        obj.check("SUCCESSFUL", 's');
    }
}
```

